## Reactor模型

有关Reactor模型结构，可以参考Doug Lea在 Scalable IO in Java中的介绍。这里简单介绍一下Reactor模式的典型实现：

## Reactor单线程模型

这是最简单的单Reactor单线程模型。Reactor线程负责多路分离套接字、accept新连接，并分派请求到处理器链中。该模型适用于处理器链中业务处理组件能快速完成的场景。不过，这种单线程模型不能充分利用多核资源，所以实际使用的不多。

![image](https://cdn-mineru.openxlab.org.cn/result/2026-08-10/57b86128-15b1-42c6-ba87-433dfe8245f7/d66dbc2aabcdb1e4c32c2b1cf3dad5b9731c12bfded4edc25b5ddb2086eb6dac.jpg)

这个模型和上面的NIO流程很类似，只是将消息相关处理独立到了Handler中去了。

代码实现如下：

```java
public class Reactor implements Runnable {

    final Selector selector;

    final ServerSocketChannel serverSocketChannel;

    public static void main(String[] args) throws IOException {
    new Thread(new Reactor(1234)).start();
    }

    public Reactor(int port) throws IOException {
    selector = Selector.open();
    serverSocketChannel = ServerSocketChannel.open();
    serverSocketChannel.socket().bind(new InetSocketAddress(port));
    serverSocketChannel.configureBlocking(false);
    SelectionKey key = serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);
    key.attach(new Acceptor());
    }

    @Override
    public void run() {
    while (!Thread.interrupted()) {
    try {
    selector.select();
    SetSelectionKey> selectionKeys = selector.selectedKeys()
    for (SelectionKey selectionKey : selectionKeys) {
    dispatch(selectionKey);
    }
    selectionKeys.clear();
    } catch (IOException e) {
    e.printStackTrace();
    }
    }
    }

    private void dispatch(SelectionKey selectionKey) {
    Runnable run = (Runnable) selectionKeycaption();
    if (run != null) {
    run.run();
    }
    }

    class Acceptor implements Runnable {

    @Override
    public void run() {
    try {
    SocketChannel channel = serverSocketChannel.accept();
    if (channel != null) {
    new Handler(selector, channel);
    }
    } catch (IOException e) {
    e.printStackTrace();
    }
} 
```

```java
class Handler implements Runnable {

    private final static int DEFAULT_SIZE = 1024;

    private final SocketChannel socketChannel;

    private final SelectionKey selectionKey;

    private static final int READING = 0;

    private static final int SENDING = 1;

    private int state = READING;

    ByteBuffer inputBuffer = ByteBuffer.allocate(DEFAULT_SIZE);

    ByteBuffer outputBuffer = ByteBuffer.allocate(DEFAULT_SIZE);

    public Handler(Selector selector, SocketChannel channel) throws IOException {
    this.socketChannel = channel;
    socketChannel.configureBlocking(false);
    this.selectionKey = socketChannel.register(selector, 0);
    selectionKey.attach(this);
    selectionKey.interestOps(SelectionKey.OP_READ);
    selector.wakeup();
    }

    @Override
    public void run() {
    if (state == READING) {
    read();
    } else if (state == SENDING) {
    write();
    }
    }

    class Sender implements Runnable {

    @Override
    public void run() {
    try {
    socketChannel.write(outputBuffer);
    } catch (IOException e) {
    e.printStackTrace();
    }
    if (outIsComplete()) {
    selectionKey.cancel();
    }
    }
} 
```

```java
private void write() {
    try {
    socketChannel.write(outputBuffer);
    } catch (IOException e) {
    e.printStackTrace();
    }
    while (outIsComplete()) {
    selectionKey.cancel();
    }
}

private void read() {
    try {
    socketChannel.read(inputBuffer);
    if (inputIsComplete()) {
    process();
    System.out.println("接到来自客户端（" + socketChannel.socket().getInetAddress().getHostAddress() + ")的消息：" + new String(inputBuffer.array()));
    selectionKey.attach(new Sender());
    selectionKey.interestOps(SelectionKey.OP_WRITE);
    selectionKey.selector().wakeup();
    }
    } catch (IOException e) {
    e.printStackTrace();
    }
}

public boolean inputIsComplete() {
    return true;
}

public boolean outIsComplete() {
    return true;

}

