Student stu2 = new Student("陈卫泽", 25, '男', 158, "13709394767");
Student stu3 = new Student("刘德华", 18, '男', 180, "18976341237");
Student stu4 = new Student("陈晓东", 20, '男', 170, "13602003113");
Student stu5 = new Student("苏亦晨", 19, '男', 185, "15521134916");
// collections的sort方法只能传递list类型的，所以就用arraylist
