public class ClassEncrypt extends MyClassLoader{
    public static void main(String[] args) throws IOException {
    //要加密的字节码.class文件
    String
srcPath="E:/workspace.fu/ClassLoaderTest/bin/com/tao/test/ClassTest.class";
