    cypher(fis, ofs);//加密
    fis.close();
    ofs.close();
}

//简单的加密，用于测试。将所有二进制位取反，即0变成1，1变成0
private static void cypher(InputStream in,OutputStream out) throws IOException{
    int b=-1;
    while((b=in.read())!=-1){
    out.write(b^0xff);
    }
}
